import type { ReactNode } from "react";

/**
 * A small Markdown renderer for the validation reports (generated by our own scripts): headings,
 * paragraphs, bullet lists, tables, **bold** and `code`. It builds React elements, never HTML
 * strings, so nothing in a report can inject markup.
 */
export function renderMarkdown(source: string): ReactNode[] {
  const lines = source.replace(/\r\n/g, "\n").split("\n");
  const out: ReactNode[] = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (!line.trim()) { i++; continue; }
    const heading = /^(#{1,3})\s+(.*)$/.exec(line);
    if (heading) {
      const level = heading[1].length;
      const cls = level === 1 ? "text-display-l text-fg" : level === 2 ? "mt-12 text-display-m text-fg" : "mt-8 text-ui font-medium text-fg";
      const Tag = (`h${Math.min(level + 1, 4)}`) as "h2" | "h3" | "h4";
      out.push(<Tag key={i} className={cls}>{inline(heading[2])}</Tag>);
      i++;
      continue;
    }
    if (line.startsWith("|")) {
      const block: string[] = [];
      while (i < lines.length && lines[i].startsWith("|")) block.push(lines[i++]);
      out.push(table(block, i));
      continue;
    }
    if (/^[-*]\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^[-*]\s+/.test(lines[i])) items.push(lines[i++].replace(/^[-*]\s+/, ""));
      out.push(<ul key={i} className="mt-4 list-disc space-y-2 pl-5">{items.map((t, k) => <li key={k}>{inline(t)}</li>)}</ul>);
      continue;
    }
    const para: string[] = [];
    while (i < lines.length && lines[i].trim() && !/^(#{1,3}\s|\||[-*]\s)/.test(lines[i])) para.push(lines[i++]);
    out.push(<p key={i} className="mt-4">{inline(para.join(" "))}</p>);
  }
  return out;
}

function table(rows: string[], key: number): ReactNode {
  const cells = (r: string) => r.replace(/^\||\|$/g, "").split("|").map((c) => c.trim());
  const [head, , ...body] = rows;
  return (
    <div key={key} className="mt-6 overflow-x-auto" tabIndex={0} role="region" aria-label="Table">
      <table className="w-full min-w-[32rem] text-left text-ui">
        <thead><tr>{cells(head).map((c, k) => <th key={k} scope="col" className="pb-2 pr-4 font-medium text-fg">{inline(c)}</th>)}</tr></thead>
        <tbody>{body.map((r, k) => <tr key={k} className="border-t border-line align-top">{cells(r).map((c, j) => <td key={j} className="py-2 pr-4">{inline(c)}</td>)}</tr>)}</tbody>
      </table>
    </div>
  );
}

function inline(text: string): ReactNode[] {
  const parts = text.split(/(\*\*[^*]+\*\*|`[^`]+`)/g).filter(Boolean);
  return parts.map((p, k) => {
    if (p.startsWith("**") && p.endsWith("**")) return <strong key={k} className="font-medium text-fg">{p.slice(2, -2)}</strong>;
    if (p.startsWith("`") && p.endsWith("`")) return <code key={k} className="rounded-sm bg-surface px-1 text-meta">{p.slice(1, -1)}</code>;
    return p;
  });
}
